protected _trapFocus(): void {
    if (this._legacyFocusDestroyed) {
      return;
    }
    const focus = () => {
      if (this._legacyFocusDestroyed) {
        return;
      }
      this._legacyFocusCleanup?.();
      const cleanup = focusLegacyDialogInitially({
        element: this._elementRef.nativeElement,
        config: this._config,
        factory: this._focusTrapFactory,
        checker: this._legacyFocusChecker,
        renderer: this._legacyFocusRenderer || {
          listen: (target: HTMLElement, event: string, callback: EventListener) => {
            target.addEventListener(event, callback);
            return () => target.removeEventListener(event, callback);
          },
        },
        ngZone: this._ngZone,
        isBrowser: this._isBrowser(),
        isDestroyed: () => this._legacyFocusDestroyed,
        onFocusSettled: () => {
          if (!this._legacyFocusDestroyed) {
            this._legacyFocusNotifications.next();
          }
        },
      });
      if (this._legacyFocusDestroyed) {
        cleanup?.();
      } else {
        this._legacyFocusCleanup = cleanup;
      }
    };
    if ((this._config.autoFocus === true || this._config.autoFocus === 'first-tabbable')
        && !this._ngZone.isStable) {
      this._legacyFocusStableSubscriptions.add(this._ngZone.onStable.pipe(take(1)).subscribe(focus));
    } else {
      focus();
    }
  }

ngOnDestroy(): void {
    if (this._legacyFocusDestroyed) {
      return;
    }
    this._legacyFocusDestroyed = true;
    destroyLegacyDialogContainerState(this);
    try {
      this._legacyFocusStableSubscriptions.unsubscribe();
      this._restoreLegacyFocus();
    } finally {
      try {
        this._legacyBackdropSubscription?.unsubscribe();
      } finally {
        this._legacyBackdropSubscription = null;
        try {
          this._legacyFocusTrap?.destroy();
        } finally {
          this._legacyFocusTrap = null;
          try {
            this._legacyFocusCleanup?.();
          } finally {
            this._legacyFocusCleanup = null;
            this._legacyFocusNotifications.complete();
          }
        }
      }
    }
  }

export interface LegacyDialogInitialFocusContext {
  element: HTMLElement;
  config: Pick<MatDialogConfig, 'autoFocus'>;
  factory: FocusTrapFactory;
  checker: InteractivityChecker;
  renderer: Pick<Renderer2, 'listen'>;
  ngZone: NgZone;
  isBrowser: boolean;
  isDestroyed: () => boolean;
  onFocusSettled: () => void;
}

export function focusLegacyDialogInitially(context: LegacyDialogInitialFocusContext,
    options?: FocusOptions): (() => void) | null {
  if (!context.isBrowser) {
    context.onFocusSettled();
    return null;
  }
  const {element, config, factory, checker, renderer, ngZone} = context;
  switch (config.autoFocus) {
    case false:
    case 'dialog':
      if (!legacyDialogContainsFocus(element)) {
        element.focus(options);
      }
      context.onFocusSettled();
      return null;
    case true:
    case 'first-tabbable': {
      // This temporary selector uses the public initial-element algorithm.
      // Defer anchors: the enclosing container already owns the real tab trap.
      const selection = factory.create(element, true);
      let focused: boolean;
      try {
        focused = selection.focusInitialElement(options);
      } finally {
        selection.destroy();
      }
      if (focused) {
        context.onFocusSettled();
        return null;
      }
      // The original focusInitialElementWhenReady promise deferred only its fallback.
      let canceled = false;
      Promise.resolve().then(() => {
        if (!canceled && !context.isDestroyed()) {
          element.focus(options);
          context.onFocusSettled();
        }
      });
      return () => { canceled = true; };
    }
  }
  const selector = config.autoFocus === 'first-heading'
    ? 'h1, h2, h3, h4, h5, h6, [role="heading"]'
    : config.autoFocus as string;
  const target = element.querySelector<HTMLElement>(selector);
  let cleanup: (() => void) | null = null;
  if (target) {
    if (!checker.isFocusable(target)) {
      target.tabIndex = -1;
      ngZone.runOutsideAngular(() => {
        let restored = false;
        const restore = () => {
          if (restored) {
            return;
          }
          restored = true;
          stopBlur();
          stopMouseDown();
          target.removeAttribute('tabindex');
        };
        const stopBlur = renderer.listen(target, 'blur', restore);
        const stopMouseDown = renderer.listen(target, 'mousedown', restore);
        cleanup = restore;
      });
    }
    target.focus(options);
  }
  context.onFocusSettled();
  return cleanup;
}

